const $=id=>document.getElementById(id);
let round=0,hidden=0,pops=0,active=false,deadline=0,tick=null,sound=false,audio=null;
function popSound(){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.frequency.setValueAtTime(480,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(70,audio.currentTime+.085);gain.gain.setValueAtTime(.15,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.09);osc.start();osc.stop(audio.currentTime+.1);}catch{}}
function setup(){clearInterval(tick);active=false;pops=0;$('pops').textContent='00';$('time').textContent='30';$('timebar').style.width='100%';$('timebar').style.background='#b59ad9';$('status').textContent='READY WHEN YOU ARE';$('round').textContent=`${String(round+1).padStart(2,'0')} / 07`;$('startpanel').hidden=false;$('board').replaceChildren();for(let i=0;i<63;i++){const b=document.createElement('button');b.className='bubble';b.disabled=true;b.setAttribute('aria-label',`Pop bubble ${i+1}`);b.onclick=()=>pop(i,b);$('board').append(b);}}
function start(){hidden=Math.floor(Math.random()*63);deadline=Date.now()+30000;active=true;$('startpanel').hidden=true;$('status').textContent='FIND THE HIDDEN STAR';[...$('board').children].forEach(b=>b.disabled=false);tick=setInterval(update,50);}
function update(){if(!active)return;const left=Math.max(0,deadline-Date.now());$('time').textContent=String(Math.ceil(left/1000)).padStart(2,'0');$('timebar').style.width=`${left/300}%`;if(left<10000)$('timebar').style.background='#e87969';if(left===0)finish(false);}
function pop(i,b){if(!active)return;if(Date.now()>=deadline){finish(false);return;}b.disabled=true;b.classList.add('popped');pops++;$('pops').textContent=String(pops).padStart(2,'0');popSound();if(i===hidden)finish(true);}
function finish(won){if(!active)return;active=false;clearInterval(tick);if(!won){$('time').textContent='00';$('timebar').style.width='0%';}[...$('board').children].forEach(b=>b.disabled=true);const c=window.characters[round];$('status').textContent=won?'STAR FOUND!':'TIME’S UP';$('resultlabel').textContent=won?'THAT WAS A STAR-WORTHY POP':'TIME’S UP. HERE’S YOUR STAR.';$('resulttitle').textContent=won?`You found ${c.name}!`:c.name;$('resulttext').textContent=won?c.foundText:c.timeoutText;$('art').replaceChildren();const src=won?c.foundImage:c.timeoutImage;if(src){const img=document.createElement('img');img.src=src;img.alt=`${c.name}${won?'':' — alternate image'}`;img.onerror=()=>{$('art').textContent='Image unavailable';};$('art').append(img);}else{const span=document.createElement('span');span.textContent=`${won?'★':'✳'} ${c.name} · ${won?'reveal':'alternate'} image`;$('art').append(span);}$('next').textContent=round===6?'Play again ↗':'Next character ↗';$('result').showModal();}
$('start').onclick=start;$('restart').onclick=setup;$('next').onclick=()=>{$('result').close();round=(round+1)%7;setup();};$('retry').onclick=()=>{$('result').close();setup();};$('result').addEventListener('cancel',()=>setup());$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on ♫':'Sound off ♫';$('sound').setAttribute('aria-pressed',String(sound));if(sound)popSound();};setup();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'start_bubble_round',description:'Start the current 30-second bubble hunt.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(){if(active||$('result').open)throw new Error('Finish the current round first.');start();return {round:round+1,seconds:30};}},{name:'pop_bubble',description:'Pop one numbered bubble in the active round.',inputSchema:{type:'object',properties:{bubble:{type:'integer',minimum:1,maximum:63}},required:['bubble'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!Number.isInteger(input.bubble)||input.bubble<1||input.bubble>63)throw new Error('Choose bubble 1–63.');const b=$('board').children[input.bubble-1];if(!active||b.disabled)throw new Error('Bubble is unavailable.');pop(input.bubble-1,b);return {pops,status:$('status').textContent};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
